<template>
  <div class="graph-editor">
    <div class="tools"><el-select v-model="preset" placeholder="选择起始流程" @change="choose"><el-option label="文字生成印花" value="image"/><el-option label="参考图生成印花" value="reference"/><el-option label="只保存文字输入（无模型）" value="text"/></el-select><label class="import"><input type="file" accept="application/json,.json" @change="importGraph"/>导入工作流 JSON</label></div>
    <el-button v-if="assets.length < assetTotal" :loading="assetsLoading" @click="emit('load-assets')">加载更多平台图片（{{ assets.length }} / {{ assetTotal }}）</el-button>
    <div v-if="graph?.nodes" class="nodes"><section v-for="node in graph.nodes" :key="node.id"><header><strong>{{ labels[node.type] || node.type }}</strong><span>{{ node.id }}</span></header><el-input v-if="node.type==='textInput'" v-model="node.config.text" type="textarea" :rows="3" placeholder="默认文字，创作者可在复制时替换" @input="changed"/><template v-else-if="node.type==='imageInput'"><el-select v-model="node.config.assetIds" multiple filterable placeholder="选择具有使用权的平台图片" style="width:100%" @change="changed"><el-option v-for="asset in assets" :key="asset.assetId" :label="`${asset.name} #${asset.assetId}`" :value="asset.assetId"/></el-select><p>留空则由创作者在自己的画布中选择图片。</p></template><template v-else-if="node.type==='imageGenerate'"><el-form-item label="比例"><el-select v-model="node.config.ratio" @change="changed"><el-option v-for="ratio in ['1:1','3:4','4:3','9:16','16:9']" :key="ratio" :value="ratio"/></el-select></el-form-item><el-form-item label="张数"><el-input-number v-model="node.config.count" :min="1" :max="4" :precision="0" @change="changed"/></el-form-item></template>
    <el-form-item v-if="['textGenerate','imageGenerate'].includes(node.type)" label="模型 ID"><el-input v-model="node.config.modelId" clearable placeholder="可留空，使用时由创作者选择" @input="clearModel(node)"/></el-form-item>
    </section></div>
    <el-collapse><el-collapse-item title="高级工作流配置"><el-input v-model="raw" type="textarea" :rows="14" spellcheck="false"/><el-button @click="applyRaw">应用配置</el-button></el-collapse-item></el-collapse><p v-if="error" class="error">{{ error }}</p>
  </div>
</template>
<script setup>
import{ref,watch}from'vue'
const props=defineProps({modelValue:Object,assets:{type:Array,default:()=>[]},assetTotal:{type:Number,default:0},assetsLoading:Boolean}),emit=defineEmits(['update:modelValue','load-assets'])
const graph=ref(null),raw=ref(''),preset=ref(''),error=ref(''),labels={textInput:'文字输入',imageInput:'参考图片',textGenerate:'文字生成',imageGenerate:'生成图片',imageProcess:'图片处理',productPreview:'商品预览',export:'导出'}
watch(()=>props.modelValue,value=>{graph.value=value?JSON.parse(JSON.stringify(value)):null;raw.value=JSON.stringify(value,null,2)},{immediate:true})
function changed(){raw.value=JSON.stringify(graph.value,null,2);emit('update:modelValue',JSON.parse(JSON.stringify(graph.value)))}
function clearModel(node){if(!node.config.modelId)delete node.config.modelId;changed()}
function choose(kind){const nodes=[{id:'text',type:'textInput',version:1,position:{x:0,y:50},config:{text:'请填写创作主题'}}],edges=[];if(kind!=='text'){nodes.push({id:'image',type:'imageGenerate',version:1,position:{x:410,y:50},config:{ratio:'1:1',count:1}});edges.push({id:'text-image',source:'text',sourcePort:'text',target:'image',targetPort:'text'});if(kind==='reference'){nodes.push({id:'reference',type:'imageInput',version:1,position:{x:0,y:350},config:{assetIds:[]}});edges.push({id:'ref-image',source:'reference',sourcePort:'images',target:'image',targetPort:'images'})}}graph.value={schemaVersion:1,nodes,edges};changed()}
function applyRaw(){try{const value=JSON.parse(raw.value);if(!value||value.schemaVersion!==1||!Array.isArray(value.nodes)||!Array.isArray(value.edges))throw new Error('工作流格式无效');graph.value=value;error.value='';changed()}catch(e){error.value=e.message}}
async function importGraph(event){const file=event.target.files?.[0];event.target.value='';if(!file)return;if(file.size>512*1024){error.value='JSON 文件不能超过 512 KiB';return}raw.value=await file.text();applyRaw()}
</script>
<style scoped>.tools{display:flex;gap:12px;align-items:center;margin-bottom:14px}.tools .el-select{width:220px}.import{cursor:pointer;color:var(--el-color-primary)}.import input{display:none}.nodes{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.nodes section{padding:14px;border:1px solid var(--el-border-color);border-radius:6px}.nodes header{display:flex;justify-content:space-between;margin-bottom:10px}.nodes span,.nodes p{font-size:12px;color:var(--el-text-color-secondary)}.error{color:var(--el-color-danger)}@media(max-width:600px){.nodes{grid-template-columns:1fr}.tools{flex-wrap:wrap}}</style>
